import { useState } from "react";
import { Check, X, Loader2, Sparkles } from "lucide-react";
import { toast } from "@/hooks/use-toast";
import type { Proposal } from "@/hooks/useSkillObservations";

/**
 * ProposalInbox — Phase 3 surface for the meta-skill loop.
 *
 * Lists pending principle proposals generated by the Skill Reviewer from
 * clustered observations. The user approves (promote → cross_cutting_principles
 * as active) or rejects. Methodology adapted from "One Skill to Rule Them All"
 * by Eoghan Henn (rebelytics.com), CC BY 4.0.
 */
export function ProposalInbox({
  proposals,
  reviewing,
  onRunReviewer,
  onApprove,
  onReject,
}: {
  proposals: Proposal[];
  reviewing: boolean;
  onRunReviewer: () => Promise<{ ok: boolean; error?: string; data?: { proposed?: number; reviewed?: number } }>;
  onApprove: (id: string) => Promise<{ ok: boolean; error?: string }>;
  onReject: (id: string) => Promise<{ ok: boolean; error?: string }>;
}) {
  const [busyId, setBusyId] = useState<string | null>(null);

  const runReview = async () => {
    const res = await onRunReviewer();
    if (!res.ok) {
      toast({ title: "Review failed", description: res.error, variant: "destructive" });
      return;
    }
    const proposed = res.data?.proposed ?? 0;
    const reviewed = res.data?.reviewed ?? 0;
    toast({
      title: proposed > 0 ? `${proposed} new proposal${proposed === 1 ? "" : "s"}` : "Nothing new to propose",
      description:
        proposed > 0
          ? `Clustered from ${reviewed} fresh observation${reviewed === 1 ? "" : "s"}.`
          : `Reviewed ${reviewed} observation${reviewed === 1 ? "" : "s"} — no new patterns yet.`,
    });
  };

  const handleApprove = async (id: string) => {
    setBusyId(id);
    const res = await onApprove(id);
    setBusyId(null);
    if (!res.ok) {
      toast({ title: "Could not approve", description: res.error, variant: "destructive" });
      return;
    }
    toast({ title: "Principle adopted" });
  };

  const handleReject = async (id: string) => {
    setBusyId(id);
    const res = await onReject(id);
    setBusyId(null);
    if (!res.ok) {
      toast({ title: "Could not reject", description: res.error, variant: "destructive" });
      return;
    }
    toast({ title: "Proposal dismissed" });
  };

  return (
    <div className="space-y-3 border-t border-border/40 pt-4">
      <div className="flex items-center justify-between gap-3">
        <div className="text-[10px] text-muted-foreground font-mono uppercase tracking-wider">
          Pending proposals · {proposals.length}
        </div>
        <button
          type="button"
          onClick={() => void runReview()}
          disabled={reviewing}
          className="inline-flex items-center gap-1.5 text-[11px] text-primary hover:text-primary/80 transition-colors disabled:opacity-50"
        >
          {reviewing ? (
            <Loader2 className="w-3 h-3 animate-spin" />
          ) : (
            <Sparkles className="w-3 h-3" />
          )}
          {reviewing ? "Reviewing…" : "Run review"}
        </button>
      </div>

      {proposals.length === 0 && !reviewing && (
        <p className="text-xs text-muted-foreground/70 leading-relaxed">
          No pending proposals. When enough fresh observations accumulate, run
          review and the system will cluster them into candidate principles for
          your approval.
        </p>
      )}

      {proposals.map((p) => (
        <div
          key={p.id}
          className="rounded-xl border border-primary/20 bg-primary/[0.04] p-3 space-y-2"
        >
          <div className="flex items-start justify-between gap-3">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-sm font-medium text-foreground/90">{p.title}</span>
                <span className="text-[9px] uppercase tracking-wider text-muted-foreground font-mono px-1.5 py-0.5 rounded bg-muted/40">
                  {p.observationCount} obs · {(p.confidence * 100).toFixed(0)}%
                </span>
              </div>
              <p className="text-xs text-foreground/75 mt-1 leading-relaxed">{p.principle}</p>
              {p.rationale && (
                <p className="text-[11px] text-muted-foreground/80 mt-1.5 italic leading-relaxed">
                  {p.rationale}
                </p>
              )}
            </div>
          </div>
          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              type="button"
              disabled={busyId === p.id}
              onClick={() => void handleReject(p.id)}
              className="inline-flex items-center gap-1.5 text-[11px] text-muted-foreground hover:text-foreground transition-colors px-2 py-1 disabled:opacity-50"
            >
              <X className="w-3 h-3" />
              Dismiss
            </button>
            <button
              type="button"
              disabled={busyId === p.id}
              onClick={() => void handleApprove(p.id)}
              className="inline-flex items-center gap-1.5 text-[11px] bg-primary text-primary-foreground rounded-md px-2.5 py-1 disabled:opacity-50"
            >
              {busyId === p.id ? (
                <Loader2 className="w-3 h-3 animate-spin" />
              ) : (
                <Check className="w-3 h-3" />
              )}
              Adopt principle
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}
